select throws_ok($$select wedecent_private.checkpoint_participant_vector_hash('[]'::jsonb)$$,'22023',null,'empty participant vector rejected');
select is(encode(extensions.digest(wedecent_private.checkpoint_event_v2_encoding_from_participants('finalize','device','wd_aaaaaaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef',decode(repeat('11',32),'hex'),'[{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":7,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"}]'::jsonb,decode(repeat('33',32),'hex'),42,7),'sha256'),'hex'),'c1ce98f4710d51dc24a0f93cd1156fd47a656fac946fd825c0b5d3ea4310c0fb','PostgreSQL event hash matches Go golden vector');
select throws_ok($$select wedecent_private.checkpoint_participant_vector_hash('[{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":7,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"},{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":7,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"}]'::jsonb)$$,'22023',null,'duplicate participant rejected');
select throws_ok($$select wedecent_private.checkpoint_event_v2_encoding_from_participants('finalize','device','wd_aaaaaaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef',decode(repeat('11',32),'hex'),'[{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":8,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"}]'::jsonb,decode(repeat('33',32),'hex'),42,7)$$,'22023',null,'device event revocation epoch must match participant');
select is(encode(wedecent_private.checkpoint_participant_vector_hash('[{"device_id":"wd_bbbbbbbbbbbbbbbb","account_id":"33333333-3333-4333-8333-333333333333","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":3,"head_generation":9,"head_hash":"4444444444444444444444444444444444444444444444444444444444444444"},{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":7,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"}]'::jsonb),'hex'),'4a6cc993928b682113129dee8a23167b6e4b54bc4604b27dd2babd0fcacd856b','participant order vector matches canonical golden digest');
select ok(wedecent_private.checkpoint_v1_transition_matches('[{"device_id":"wd_bbbbbbbbbbbbbbbb","account_id":"33333333-3333-4333-8333-333333333333","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":3,"head_generation":9,"head_hash":"4444444444444444444444444444444444444444444444444444444444444444"},{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":7,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"}]'::jsonb,'[{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":7,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"},{"device_id":"wd_bbbbbbbbbbbbbbbb","account_id":"33333333-3333-4333-8333-333333333333","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":3,"head_generation":9,"head_hash":"4444444444444444444444444444444444444444444444444444444444444444"}]'::jsonb),'historical participant order is canonicalized identically');
select throws_ok($select wedecent_private.checkpoint_participant_vector_hash('[{"device_id":"wd_aaaaaaaaaaaaaaaa","account_id":"11111111-1111-4111-8111-111111111111","organization_id":"22222222-2222-4222-8222-222222222222","revocation_epoch":7,"head_generation":41,"head_hash":"3333333333333333333333333333333333333333333333333333333333333333"}]'::jsonb)$,'22023',null,'null participant fields rejected');
